import com.spinplayer.app.ArtworkUrl;
public class ArtworkUrlTest{public static void main(String[] args)throws Exception{for(String u:new String[]{"https://lh3.googleusercontent.com/cover=w544-h544","https://yt3.ggpht.com/cover","https://i.ytimg.com/vi/12345678901/hqdefault.jpg","https://i1.sndcdn.com/artworks-test-large.jpg","//lh3.googleusercontent.com/cover"})if(!ArtworkUrl.allowed(u).startsWith("https://"))throw new AssertionError();for(String u:new String[]{"http://lh3.googleusercontent.com/a","https://googleusercontent.com.evil.test/a","https://evilgoogleusercontent.com/a","https://user@lh3.googleusercontent.com/a","https://lh3.googleusercontent.com:444/a","file:///tmp/a"}){try{ArtworkUrl.allowed(u);throw new AssertionError(u);}catch(java.io.IOException expected){}}if(!ArtworkUrl.fallback("https://music.youtube.com/watch?v=12345678901&x=1").equals("https://i.ytimg.com/vi/12345678901/hqdefault.jpg"))throw new AssertionError();System.out.println("PASS: YouTube Music thumbnail hosts, protocol-relative URLs, thumbnail fallback, unsafe URL rejection");}}
